import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture as textureNode } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const resources = [];

  // Load sprite texture
  const spriteTexture = ctx.textureLoader.load(config.assets.imageUrl);
  spriteTexture.colorSpace = THREE.SRGBColorSpace;

  // Create sprite plane (atlas aspect ratio: 512x320 = 1.6:1)
  const atlasAspect = 512 / 320;
  const spriteW = 1.6;
  const spriteH = spriteW / atlasAspect;

  const spriteGeom = new THREE.PlaneGeometry(spriteW, spriteH);
  const spriteMat = new MeshBasicNodeMaterial({
    colorNode: textureNode(spriteTexture),
  });
  const spriteMesh = new THREE.Mesh(spriteGeom, spriteMat);
  spriteMesh.position.z = -0.05;
  group.add(spriteMesh);

  resources.push(spriteGeom, spriteMat, spriteTexture);

  // Render text using font atlas if available
  if (config.textContent && ctx.fontAtlas) {
    const textMesh = ctx.fontAtlas.createText(config.textContent, {
      font: 'display',
      size: 0.34,
      weight: 400,
      color: 0x16161d,
      align: 'center',
    });
    if (textMesh) {
      textMesh.position.z = 0.05;
      group.add(textMesh);
    }
  }

  // Apply scene position
  group.position.set(0, 3, 0);

  // Setup cleanup
  group.userData.cleanup = () => {
    resources.forEach(res => res.dispose?.());
  };

  group.userData.handlers = {};

  return group;
}
